    version: 1,
    boardCode: 'np1-4-1',
    matched: [],
    selection: { kind: 'closed' },
    moves: 0,
    elapsedMs: 0,
    started: false,
  });
  await page.locator('summary').click();
  await page.getByLabel('Snapshot JSON', { exact: true }).fill(JSON.stringify({
    name: 'Do not store this name',
    version: 2,
    boardCode: 'np1-6-1',
    matched: [],
    selection: { kind: 'one', index: 5 },
    moves: 0,
    elapsedMs: 500,
    started: true,
  }));
  await page.getByRole('button', { name: 'Load snapshot', exact: true }).click();
  await expect(name).toHaveValue('Do not store this name');
  await name.fill('Nor this edit');
  expect(await page.evaluate((key) => JSON.parse(localStorage.getItem(key) ?? 'null'), PREFERENCES_KEY)).toEqual({
    schemaVersion: 1,
    size: 6,
    bestMoves: {},
  });
  await page.reload();
  await expect(page.locator('.card')).toHaveCount(36);
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toHaveCount(0);
  expect(await exportedSnapshot(page)).toMatchObject({ version: 1, started: false, elapsedMs: 0 });
  await page.locator('summary').click();
  await expect(name).toHaveValue('');
});

